import { describe, test, expect } from 'bun:test';
import { hmac } from './hmac.js';
import { sha224 } from './sha224.js';
import { sha256 } from './sha256.js';
import { sha384 } from './sha384.js';
import { sha512 } from './sha512.js';
import { sha512_224 } from './sha512_224.js';
import { sha512_256 } from './sha512_256.js';
import { sha3 } from './sha3.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha256 = sha256.factory(_ba, _utf8);
const _sha224 = sha224.factory(_sha256);
const _sha512 = sha512.factory(_ba, _utf8);
const _sha384 = sha384.factory(_sha512);
const _sha512_224 = sha512_224.factory(_sha512);
const _sha512_256 = sha512_256.factory(_sha512);
const _sha3 = sha3.factory(_ba, _utf8);
const _hmac = hmac.factory(_ba, _utf8, _sha256);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));
const fromHex = (s) => _ba.ui8_to_ba(_hex.toBytes(s));

describe('hmac module', () => {

    test('module metadata', () => {
        expect(hmac.name).toBe('hmac');
        expect(hmac.dependencies).toEqual(['bitArray', 'utf8', 'sha256']);
    });

    describe('RFC 4231 HMAC-SHA-256 vectors', () => {
        test('test case 1: 20-byte key of 0x0b, "Hi There"', () => {
            const key = fromHex('0b'.repeat(20));
            const data = 'Hi There';
            const mac = new _hmac.fn(key).encrypt(data);
            expect(toHex(mac))
                .toBe('b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7');
        });

        test('test case 2: short key "Jefe", "what do ya want for nothing?"', () => {
            const mac = new _hmac.fn('Jefe').encrypt('what do ya want for nothing?');
            expect(toHex(mac))
                .toBe('5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843');
        });

        test('test case 3: 20-byte 0xaa key, 50 x 0xdd', () => {
            const key = fromHex('aa'.repeat(20));
            const data = fromHex('dd'.repeat(50));
            const mac = new _hmac.fn(key).encrypt(data);
            expect(toHex(mac))
                .toBe('773ea91e36800e46854db8ebd09181a72959098b3ef8c122d9635514ced565fe');
        });

        test('test case 4: 25-byte chained key, 50 x 0xcd', () => {
            const key = fromHex('0102030405060708090a0b0c0d0e0f10111213141516171819');
            const data = fromHex('cd'.repeat(50));
            const mac = new _hmac.fn(key).encrypt(data);
            expect(toHex(mac))
                .toBe('82558a389a443c0ea4cc819899f2083a85f0faa3e578f8077a2e3ff46729665b');
        });

        test('test case 6: 131-byte key (>64 -> hashed first)', () => {
            const key = fromHex('aa'.repeat(131));
            const data = 'Test Using Larger Than Block-Size Key - Hash Key First';
            const mac = new _hmac.fn(key).encrypt(data);
            expect(toHex(mac))
                .toBe('60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54');
        });
    });

    describe('HMAC-SHA-512 (custom hash arg)', () => {
        test('test case 1: 20-byte 0x0b key, "Hi There"', () => {
            const key = fromHex('0b'.repeat(20));
            const mac = new _hmac.fn(key, _sha512).encrypt('Hi There');
            expect(toHex(mac))
                .toBe('87aa7cdea5ef619d4ff0b4241a1d6cb02379f4e2ce4ec2787ad0b30545e17cdedaa833b7d6b8a702038b274eaea3f4e4be9d914eeb61f1702e696c203a126854');
        });
    });

    describe('streaming and reset', () => {
        test('chunked update matches one-shot', () => {
            const key = 'secret-key';
            const oneShot = toHex(new _hmac.fn(key).encrypt('hello world'));
            const h = new _hmac.fn(key);
            h.update('hello ');
            h.update('world');
            const stream = toHex(h.digest());
            expect(stream).toBe(oneShot);
        });

        test('reset allows reuse after digest', () => {
            const h = new _hmac.fn('k');
            h.update('first');
            const a = toHex(h.digest());
            h.update('first');
            const b = toHex(h.digest());
            expect(a).toBe(b);
        });

        test('encrypt on already-updated instance returns false (not crash)', () => {
            const h = new _hmac.fn('k');
            h.update('partial');
            const result = h.encrypt('more');
            expect(result).toBe(false);
        });

        test('mac is alias for encrypt', () => {
            const h = new _hmac.fn('k');
            expect(h.mac).toBe(_hmac.fn.prototype.encrypt);
        });
    });

    describe('verify (constant-time)', () => {
        test('accepts correct tag', () => {
            const key = fromHex('0b'.repeat(20));
            const tag = new _hmac.fn(key).encrypt('Hi There');
            expect(_hmac.verify(key, 'Hi There', tag)).toBe(true);
        });

        test('rejects single-bit tampered tag', () => {
            const key = fromHex('0b'.repeat(20));
            const tag = new _hmac.fn(key).encrypt('Hi There');
            // Flip one bit in last word
            const tampered = tag.slice();
            tampered[tampered.length - 1] ^= 0x00000001;
            expect(_hmac.verify(key, 'Hi There', tampered)).toBe(false);
        });

        test('rejects different message', () => {
            const key = fromHex('0b'.repeat(20));
            const tag = new _hmac.fn(key).encrypt('Hi There');
            expect(_hmac.verify(key, 'Hi There!', tag)).toBe(false);
        });

        test('rejects different key', () => {
            const tag = new _hmac.fn('k1').encrypt('msg');
            expect(_hmac.verify('k2', 'msg', tag)).toBe(false);
        });

        test('verify with custom hash module', () => {
            const tag = new _hmac.fn('k', _sha512).encrypt('msg');
            expect(_hmac.verify('k', 'msg', tag, _sha512)).toBe(true);
        });
    });
});

// ============================================================================
// ACVP HMAC-SHA2-{224,256,384,512}-2.0 (NIST CAVP vectors)
// ----------------------------------------------------------------------------
// Sources: references/NIST/ACVP-Server-1.1.0.42/gen-val/json-files/HMAC-SHA2-*-2.0/
// Coverage strategy:
//   - 1 testGroup x 150 AFT per variant ; sub-sample = every 5th tcId + min/max
//     anchors over keyLen/msgLen/macLen. All ACVP HMAC-SHA2 vectors are
//     byte-aligned for key/msg/mac (verified at extract time).
//   - macLen variation : tag truncated to first N bits via bitArray.clamp.
//   - HMAC-SHA3 : NOT integrated -- sha3.js exposes pure functions, not the
//     { fn, hash } shape required by hmac.fn. Documented as P2 limit in
//     hmac.acvp.md.
// ============================================================================

const _shaModules = {
    sha224:     _sha224,
    sha256:     _sha256,
    sha384:     _sha384,
    sha512:     _sha512,
    sha512_224: _sha512_224,
    sha512_256: _sha512_256,
    sha3_224:   _sha3.sha3_224_hash,
    sha3_256:   _sha3.sha3_256_hash,
    sha3_384:   _sha3.sha3_384_hash,
    sha3_512:   _sha3.sha3_512_hash,
};

const truncateMac = (ba, macBits) => _ba.clamp(ba, macBits);

const macHex = (variant, key, msg, macBits) => {
    const tag = new _hmac.fn(key, _shaModules[variant]).encrypt(msg);
    return toHex(truncateMac(tag, macBits));
};

