describe('hmac - ACVP HMAC-SHA2-224-2.0', () => {
    describe('AFT vectors (sub-sampled 36/150)', () => {
        test.each(HMAC_SHA224_AFT)('tcId=$tc (keyLen=$kl, msgLen=$ml, macLen=$mac_l bits)', (v) => {
            const key = fromHex(v.key);
            const msg = fromHex(v.msg);
            expect(macHex('sha224', key, msg, v.mac_l)).toBe(v.mac.toLowerCase());
        });
    });
});

