describe('hmac - ACVP HMAC-SHA2-512-224-2.0', () => {
    describe('AFT vectors (sub-sampled 31/150)', () => {
        test.each(HMAC_SHA512_224_AFT)('tcId=$tc (keyLen=$kl, msgLen=$ml, macLen=$mac_l bits)', (v) => {
            const key = fromHex(v.key);
            const msg = fromHex(v.msg);
            expect(macHex('sha512_224', key, msg, v.mac_l)).toBe(v.mac.toLowerCase());
        });
    });
});

describe('hmac - ACVP HMAC-SHA2-512-256-2.0', () => {
    describe('AFT vectors (sub-sampled 31/150)', () => {
        test.each(HMAC_SHA512_256_AFT)('tcId=$tc (keyLen=$kl, msgLen=$ml, macLen=$mac_l bits)', (v) => {
            const key = fromHex(v.key);
            const msg = fromHex(v.msg);
            expect(macHex('sha512_256', key, msg, v.mac_l)).toBe(v.mac.toLowerCase());
        });
    });
});
